mapper.select:
select  from mst_proc p
p.use_yn = #{useYn}
order by p.sort_no, p.proc_cd

mapper.sql:
from mst_proc p

    and p.use_yn = #{useYn}
    and (p.proc_cd ilike #{kw} escape '\' or p.proc_nm ilike #{kw} escape '\')

mapper.update:
update mst_proc
   set proc_nm = #{f.procNm}, proc_cat = #{f.procCat}, outsrc_yn = #{f.outsrcYn}, sort_no = #{f.sortNo},
       use_yn = #{f.useYn}, remark = #{f.remark}, row_ver = row_ver + 1, updated_at = now(), updated_by = #{by}
 where proc_id = #{id} and row_ver = #{f.rowVer}

update mst_routing
   set rev = #{f.rev}, valid_from = #{f.validFrom}, change_no = #{f.changeNo}, change_reason = #{f.changeReason},
       remark = #{f.remark}, row_ver = row_ver + 1, updated_at = now(), updated_by = #{by}
 where routing_id = #{id} and status = 'DRAFT' and row_ver = #{f.rowVer}

update mst_routing set status = 'RELEASED', released_at = now(), released_by = #{by},
                       row_ver = row_ver + 1, updated_at = now(), updated_by = #{by}
 where routing_id = #{id} and status = 'DRAFT' and row_ver = #{rowVer}

update mst_routing_step
   set op_seq = #{s.opSeq}, proc_id = #{s.procId}, node_id = #{s.nodeId}, std_ct_sec = #{s.stdCtSec},
       units_per_cycle = #{s.unitsPerCycle}, setup_min = #{s.setupMin}, remark = #{s.remark},
       row_ver = row_ver + 1, updated_at = now(), updated_by = #{by}
 where step_id = #{s.stepId} and routing_id = #{routingId}

update mst_routing_param
   set param_cd = #{p.paramCd}, param_nm = #{p.paramNm}, unit_cd = #{p.unitCd}, unit_nm = #{p.unitNm}, target_val = #{p.targetVal},
       lsl = #{p.lsl}, usl = #{p.usl}, sort_no = #{p.sortNo},
       row_ver = row_ver + 1, updated_at = now(), updated_by = #{by}
 where param_id = #{p.paramId} and step_id = #{stepId}

mapper.insert:
insert into mst_routing_step (comp_cd, routing_id, op_seq, proc_id, node_id, std_ct_sec, units_per_cycle,
                              setup_min, remark, created_by, updated_by)
select comp_cd, #{toId}, op_seq, proc_id, node_id, std_ct_sec, units_per_cycle, setup_min, remark, #{by}, #{by}
  from mst_routing_step where routing_id = #{fromId}
 order by op_seq
